from openpyxl import load_workbook, Workbook
from openpyxl.worksheet.copier import WorksheetCopy
from openpyxl.utils import get_column_letter
from copy import copy
from datetime import datetime
from pathlib import Path
from docx import Document

PLAN = Path('/root/Cycle_Plan.xlsx')
EVENTS = Path('/root/Count_Event_Log.xlsx')
TEMPLATE = Path('/root/Cycle_Template.xlsx')
OUT_XLSX = Path('/root/Cycle_Count_Variance_Audit.xlsx')
OUT_DOCX = Path('/root/Cycle_Count_Variance_Brief.docx')

REQUIRED_FIRST7 = ['Facility', 'Session ID', 'Bin ID', 'Product ID', 'Expected Qty', 'Allowed Variance', 'Approval Needed']
FORMATTED_HEADERS = REQUIRED_FIRST7 + ['Missing Final Count', 'Approval Gap', 'Total Errors', 'Error Summary']
SUMMARY_HEADERS = ['Facility', 'Session ID', 'Missing Final Counts', 'Approval Gaps', 'Total Errors']


def norm(s):
    return str(s).strip().lower() if s is not None else ''


def is_blank(v):
    return v is None or (isinstance(v, str) and v.strip() == '')


def to_number(v):
    if v is None or (isinstance(v, str) and v.strip() == ''):
        return None
    if isinstance(v, (int, float)):
        return v
    try:
        return float(str(v).strip())
    except Exception:
        return None


def parse_time(v):
    if v is None:
        return None
    if isinstance(v, datetime):
        return v
    if isinstance(v, str):
        text = v.strip()
        for fmt in ('%Y-%m-%dT%H:%M:%S', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
            try:
                return datetime.strptime(text, fmt)
            except ValueError:
                pass
        try:
            return datetime.fromisoformat(text)
        except ValueError:
            return None
    return None


def rows_from_ws(ws):
    rows = []
    for row in ws.iter_rows(values_only=True):
        rows.append(list(row))
    return rows


def copy_sheet_exact(src_ws, dst_ws):
    # Copy cell values and style objects.
    for row in src_ws.iter_rows():
        for src_cell in row:
            dst_cell = dst_ws[src_cell.coordinate]
            dst_cell.value = src_cell.value
            if src_cell.has_style:
                dst_cell.font = copy(src_cell.font)
                dst_cell.fill = copy(src_cell.fill)
                dst_cell.border = copy(src_cell.border)
                dst_cell.alignment = copy(src_cell.alignment)
                dst_cell.number_format = src_cell.number_format
                dst_cell.protection = copy(src_cell.protection)
            if src_cell.hyperlink:
                dst_cell._hyperlink = copy(src_cell.hyperlink)
            if src_cell.comment:
                dst_cell.comment = copy(src_cell.comment)
    for merged_range in src_ws.merged_cells.ranges:
        dst_ws.merge_cells(str(merged_range))
    for key, dim in src_ws.column_dimensions.items():
        dst_dim = dst_ws.column_dimensions[key]
        dst_dim.width = dim.width
        dst_dim.hidden = dim.hidden
        dst_dim.outlineLevel = dim.outlineLevel
        dst_dim.collapsed = dim.collapsed
        dst_dim.bestFit = dim.bestFit
        dst_dim.style = dim.style
        dst_dim.min = dim.min
        dst_dim.max = dim.max
    for key, dim in src_ws.row_dimensions.items():
        dst_dim = dst_ws.row_dimensions[key]
        dst_dim.height = dim.height
        dst_dim.hidden = dim.hidden
        dst_dim.outlineLevel = dim.outlineLevel
        dst_dim.collapsed = dim.collapsed
        dst_dim.ht = dim.ht
        dst_dim.s = dim.s
        dst_dim.customHeight = dim.customHeight
    dst_ws.sheet_format = copy(src_ws.sheet_format)
    dst_ws.sheet_properties = copy(src_ws.sheet_properties)
    dst_ws.page_margins = copy(src_ws.page_margins)
    dst_ws.page_setup = copy(src_ws.page_setup)
    dst_ws.print_options = copy(src_ws.print_options)
    if src_ws.freeze_panes:
        dst_ws.freeze_panes = src_ws.freeze_panes


def get_col_index(headers, wanted):
    # exact first, then normalized exact, then loose alnum.
    if wanted in headers:
        return headers.index(wanted)
    nw = norm(wanted)
    for i, h in enumerate(headers):
        if norm(h) == nw:
            return i
    compact = ''.join(ch for ch in nw if ch.isalnum())
    for i, h in enumerate(headers):
        if ''.join(ch for ch in norm(h) if ch.isalnum()) == compact:
            return i
    raise KeyError(f"Required column not found: {wanted}; headers={headers}")


def load_input_data():
    plan_wb = load_workbook(PLAN, data_only=True)
    plan_ws = plan_wb[plan_wb.sheetnames[0]]
    plan_rows = rows_from_ws(plan_ws)
    plan_headers = plan_rows[0]
    plan_data = plan_rows[1:]

    events_wb = load_workbook(EVENTS, data_only=True)
    events_ws = events_wb[events_wb.sheetnames[0]]
    event_rows = rows_from_ws(events_ws)
    event_headers = event_rows[0]
    event_data = event_rows[1:]
    return plan_headers, plan_data, event_headers, event_data


def build_kept_events(event_headers, event_data):
    idx = {name: get_col_index(event_headers, name) for name in ['Facility','Session ID','Bin ID','Event Type','Count Qty']}
    timestamp_candidates = ['Event Time', 'Timestamp', 'Event Timestamp', 'Date Time', 'Datetime', 'Created At', 'Count Time']
    time_col = None
    for cand in timestamp_candidates:
        try:
            time_col = get_col_index(event_headers, cand)
            break
        except KeyError:
            pass

    kept = {}
    for pos, row in enumerate(event_data, start=2):
        # Pad row to header length.
        row = list(row) + [None] * (len(event_headers) - len(row))
        if norm(row[idx['Event Type']]) != 'final':
            continue
        if any(is_blank(row[idx[col]]) for col in ['Facility','Session ID','Bin ID','Count Qty']):
            continue
        key = (row[idx['Facility']], row[idx['Session ID']], row[idx['Bin ID']])
        event_time = parse_time(row[time_col]) if time_col is not None else None
        if key not in kept:
            kept[key] = {'row': row, 'pos': pos, 'time': event_time, 'count_qty': row[idx['Count Qty']]}
        else:
            old = kept[key]
            if time_col is not None and (event_time is not None or old['time'] is not None):
                # Prefer later parseable timestamp. If tied/unparseable, later row position wins.
                if old['time'] is None or (event_time is not None and (event_time > old['time'] or (event_time == old['time'] and pos > old['pos']))):
                    kept[key] = {'row': row, 'pos': pos, 'time': event_time, 'count_qty': row[idx['Count Qty']]}
            elif pos > old['pos']:
                kept[key] = {'row': row, 'pos': pos, 'time': event_time, 'count_qty': row[idx['Count Qty']]}
    return kept, time_col


def build_workbook():
    plan_headers, plan_data, event_headers, event_data = load_input_data()
    plan_idx = {name: get_col_index(plan_headers, name) for name in REQUIRED_FIRST7}
    kept_events, time_col = build_kept_events(event_headers, event_data)

    template_wb = load_workbook(TEMPLATE)
    src_overview = template_wb['Overview']
    out_wb = Workbook()
    # Remove default and create sheets in exact order.
    default = out_wb.active
    out_wb.remove(default)
    overview = out_wb.create_sheet('Overview')
    copy_sheet_exact(src_overview, overview)

    raw = out_wb.create_sheet('RawData')
    raw.append(plan_headers)
    for row in plan_data:
        raw.append(row)

    formatted = out_wb.create_sheet('Formatted Data')
    formatted.append(FORMATTED_HEADERS)
    formatted_records = []
    for row in plan_data:
        row = list(row) + [None] * (len(plan_headers) - len(row))
        first7 = [row[plan_idx[name]] for name in REQUIRED_FIRST7]
        key = (row[plan_idx['Facility']], row[plan_idx['Session ID']], row[plan_idx['Bin ID']])
        ev = kept_events.get(key)
        missing = 1 if ev is None else 0
        approval_gap = 0
        if ev is not None:
            approval_needed = str(row[plan_idx['Approval Needed']]).strip().upper() if row[plan_idx['Approval Needed']] is not None else ''
            expected = to_number(row[plan_idx['Expected Qty']])
            allowed = to_number(row[plan_idx['Allowed Variance']])
            count_qty = to_number(ev['count_qty'])
            if approval_needed == 'YES' and expected is not None and allowed is not None and count_qty is not None:
                approval_gap = 1 if abs(expected - count_qty) > allowed else 0
        total = int(missing) + int(approval_gap)
        if missing and approval_gap:
            err_summary = 'Missing Final Count, Approval Gap'
        elif missing:
            err_summary = 'Missing Final Count'
        elif approval_gap:
            err_summary = 'Approval Gap'
        else:
            err_summary = 'None'
        out_row = first7 + [int(missing), int(approval_gap), int(total), err_summary]
        formatted.append(out_row)
        formatted_records.append(dict(zip(FORMATTED_HEADERS, out_row)))

    summary = out_wb.create_sheet('Summary')
    summary.append(SUMMARY_HEADERS)
    aggs = {}
    for rec in formatted_records:
        key = (rec['Facility'], rec['Session ID'])
        if key not in aggs:
            aggs[key] = {'Missing Final Counts':0, 'Approval Gaps':0, 'Total Errors':0}
        aggs[key]['Missing Final Counts'] += int(rec['Missing Final Count'])
        aggs[key]['Approval Gaps'] += int(rec['Approval Gap'])
        aggs[key]['Total Errors'] += int(rec['Total Errors'])
    included = []
    for (facility, session), vals in aggs.items():
        if vals['Total Errors'] > 0:
            included.append((facility, session, vals['Missing Final Counts'], vals['Approval Gaps'], vals['Total Errors']))
    included.sort(key=lambda x: (str(x[0]), str(x[1])))
    for r in included:
        summary.append(list(r))
    grand_missing = sum(r[2] for r in included)
    grand_gaps = sum(r[3] for r in included)
    grand_errors = sum(r[4] for r in included)
    summary.append(['Grand Total', '-', int(grand_missing), int(grand_gaps), int(grand_errors)])

    # Basic widths/readability for generated sheets, not Overview.
    for ws in [raw, formatted, summary]:
        for col in range(1, ws.max_column + 1):
            letter = get_column_letter(col)
            max_len = max(len(str(ws.cell(row=r, column=col).value or '')) for r in range(1, ws.max_row + 1))
            ws.column_dimensions[letter].width = min(max(max_len + 2, 10), 40)

    out_wb.save(OUT_XLSX)
    return {
        'plan_headers': plan_headers,
        'event_headers': event_headers,
        'kept_event_count': len(kept_events),
        'timestamp_column': event_headers[time_col] if time_col is not None else None,
        'summary_rows': included,
        'grand_totals': (grand_missing, grand_gaps, grand_errors),
    }


def build_doc(summary_rows, grand_totals):
    # Select at least two high-priority combos by highest Total Errors.
    high = sorted(summary_rows, key=lambda x: (-x[4], str(x[0]), str(x[1])))[:2]
    high_text = '; '.join(f"{fac} / {sess} ({total} total errors)" for fac, sess, miss, gaps, total in high)
    if not high_text:
        high_text = 'No facility/session combinations had exceptions'
    missing_total, gaps_total, errors_total = grand_totals

    doc = Document()
    doc.add_heading('Cycle Count Variance Audit Brief', level=1)
    p = doc.add_paragraph()
    sentences = [
        "This audit checks cycle-count completion and approval compliance for planned inventory bins.",
        "A Missing Final Count means a planned bin was never given a valid final count, while an Approval Gap means the variance between expected and actual quantity exceeded the allowed threshold on a bin marked as requiring approval.",
        f"The Summary grand totals are {int(missing_total)} Missing Final Counts, {int(gaps_total)} Approval Gaps, and {int(errors_total)} Total Errors.",
        f"The highest-priority facility/session combinations by exception count are {high_text}.",
        "Recommended actions are to prioritize recounts for missing final counts, review approval workflows for bins with approval gaps, and assign facility owners to clear the highest-error sessions first."
    ]
    p.add_run(' '.join(sentences))
    doc.save(OUT_DOCX)


def main():
    result = build_workbook()
    build_doc(result['summary_rows'], result['grand_totals'])
    print('Built:', OUT_XLSX)
    print('Built:', OUT_DOCX)
    print('Timestamp column used for latest FINAL event:', result['timestamp_column'])
    print('Kept FINAL events:', result['kept_event_count'])
    print('Summary rows:')
    for r in result['summary_rows']:
        print(r)
    print('Grand totals:', result['grand_totals'])

if __name__ == '__main__':
    main()
